#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Téma-alapú feliratkozás (pub/sub) az A2A Mesh hálózatban.
Csak a feliratkozott témáknak megfelelő üzenetek kerülnek útválasztásra.

Funkciók:
- Téma-alapú feliratkozás (pub/sub)
- Wildcard támogatás (pl. "sensors.*" illeszkedik "sensors.temp"-re)
- Hierarchikus témák (ponttal elválasztva)
- Üzenet szűrés a feliratkozások alapján
- Több mesh node közötti üzenettovábbítás
- Statisztikák a útválasztott/eldobott üzenetekről
"""

import asyncio
import json
import time
import uuid
import re
from collections import defaultdict
from dataclasses import dataclass, field, asdict
from typing import Dict, Set, Callable, Any, Optional, List, Awaitable
from enum import Enum


class MessagePriority(Enum):
    LOW = 0
    NORMAL = 1
    HIGH = 2
    URGENT = 3


@dataclass
class MeshMessage:
    """Egy A2A Mesh üzenet, témával ellátva."""
    id: str
    topic: str
    payload: Any
    sender_id: str
    timestamp: float
    priority: MessagePriority = MessagePriority.NORMAL
    headers: Dict[str, str] = field(default_factory=dict)
    ttl: int = 10  # hop count limit

    def to_dict(self) -> dict:
        d = asdict(self)
        d["priority"] = self.priority.name
        return d

    @classmethod
    def from_dict(cls, d: dict) -> "MeshMessage":
        d = dict(d)
        if isinstance(d.get("priority"), str):
            d["priority"] = MessagePriority[d["priority"]]
        return cls(**d)


@dataclass
class Subscription:
    """Egy feliratkozás egy témára."""
    subscriber_id: str
    topic_pattern: str
    callback: Optional[Callable[[MeshMessage], Awaitable[None]]] = None
    created_at: float = field(default_factory=time.time)
    message_count: int = 0


def topic_matches(pattern: str, topic: str) -> bool:
    """
    Ellenőrzi, hogy egy topic illeszkedik-e egy pattern-re.
    Támogatott wildcard-ok:
      '*' — egy szintet helyettesít (pl. 'sensors.*' -> 'sensors.temp')
      '#' — több szintet helyettesít (pl. 'sensors.#' -> 'sensors.temp.room1')
    """
    if pattern == topic:
        return True

    pattern_parts = pattern.split(".")
    topic_parts = topic.split(".")

    pi = 0
    ti = 0

    while pi < len(pattern_parts) and ti < len(topic_parts):
        p = pattern_parts[pi]
        if p == "#":
            # '#' matches everything remaining
            return True
        if p == "*" or p == topic_parts[ti]:
            pi += 1
            ti += 1
        else:
            return False

    # If pattern ended with '#' we already returned True
    # Both must be exhausted for exact match
    return pi == len(pattern_parts) and ti == len(topic_parts)


class TopicRouter:
    """
    Téma-alapú útválasztó.
    Hatékony mintaillesztés témákra, csak a releváns üzenetek kerülnek kézbesítésre.
    """

    def __init__(self):
        # topic_pattern -> set of Subscription
        self._subscriptions: Dict[str, Set[Subscription]] = defaultdict(set)
        # subscriber_id -> set of topic_patterns
        self._subscriber_topics: Dict[str, Set[str]] = defaultdict(set)
        # stats
        self._routed_count = 0
        self._dropped_count = 0
        self._publish_count = 0

    def subscribe(self, sub: Subscription) -> bool:
        """Feliratkozás egy témára. Visszatér True-val ha új feliratkozás volt."""
        if sub.topic_pattern in self._subscriber_topics[sub.subscriber_id]:
            return False  # már feliratkozott
        self._subscriptions[sub.topic_pattern].add(sub)
        self._subscriber_topics[sub.subscriber_id].add(sub.topic_pattern)
        return True

    def unsubscribe(self, subscriber_id: str, topic_pattern: Optional[str] = None) -> int:
        """
        Leiratkozás. Ha topic_pattern meg van adva, csak azt törli.
        Visszatér a törölt feliratkozások számával.
        """
        removed = 0
        if topic_pattern:
            if topic_pattern in self._subscriber_topics[subscriber_id]:
                self._subscriber_topics[subscriber_id].discard(topic_pattern)
                to_remove = [
                    s for s in self._subscriptions[topic_pattern]
                    if s.subscriber_id == subscriber_id
                ]
                for s in to_remove:
                    self._subscriptions[topic_pattern].discard(s)
                    removed += 1
                if not self._subscriptions[topic_pattern]:
                    del self._subscriptions[topic_pattern]
        else:
            patterns = list(self._subscriber_topics.get(subscriber_id, []))
            for p in patterns:
                removed += self.unsubscribe(subscriber_id, p)
            self._subscriber_topics.pop(subscriber_id, None)
        return removed

    def get_matching_subscriptions(self, topic: str) -> List[Subscription]:
        """Visszaadja az összes feliratkozást, ami illeszkedik a témára."""
        matches = []
        for pattern, subs in self._subscriptions.items():
            if topic_matches(pattern, topic):
                matches.extend(subs)
        return matches

    def record_publish(self):
        self._publish_count += 1

    def record_routed(self, count: int = 1):
        self._routed_count += count

    def record_dropped(self):
        self._dropped_count += 1

    def get_stats(self) -> dict:
        return {
            "total_subscriptions": sum(len(s) for s in self._subscriptions.values()),
            "unique_subscribers": len(self._subscriber_topics),
            "topic_patterns": len(self._subscriptions),
            "published": self._publish_count,
            "routed": self._routed_count,
            "dropped_no_match": self._dropped_count,
        }


class MeshNode:
    """
    Egy A2A Mesh node, témákra feliratkozó pub/sub rendszerrel.
    Több node kapcsolódhat egymáshoz, és továbbítják a releváns üzeneteket.
    """

    def __init__(self, node_id: str, host: str = "127.0.0.1", port: int = 0):
        self.node_id = node_id
        self.host = host
        self.port = port
        self.router = TopicRouter()
        self._peers: Dict[str, asyncio.StreamWriter] = {}
        self._server: Optional[asyncio.AbstractServer] = None
        self._local_callbacks: Dict[str, Callable] = {}
        self._seen_messages: Set[str] = set()
        self._max_seen = 10000
        self._lock = asyncio.Lock()
        self._running = False

    async def start(self) -> int:
        """Elindítja a node-ot, visszatér a tényleges porttal."""
        self._server = await asyncio.start_server(
            self._handle_incoming, self.host, self.port
        )
        sock = self._server.sockets[0]
        self.port = sock.getsockname()[1]
        self._running = True
        print(f"[{self.node_id}] Node started on {self.host}:{self.port}")
        return self.port

    async def stop(self):
        """Leállítja a node-ot."""
        self._running = False
        for peer_id, writer in list(self._peers.items()):
            writer.close()
            try:
                await writer.wait_closed()
            except Exception:
                pass
        self._peers.clear()
        if self._server:
            self._server.close()
            await self._server.wait_closed()
        print(f"[{self.node_id}] Node stopped.")

    async def connect_to_peer(self, peer_host: str, peer_port: int) -> bool:
        """Kapcsolódik egy másik mesh node-hoz."""
        try:
            reader, writer = await asyncio.open_connection(peer_host, peer_port)
            # Send handshake with our node_id and listening port
            handshake = {
                "type": "handshake",
                "node_id": self.node_id,
                "host": self.host,
                "port": self.port,
            }
            await self._send_raw(writer, handshake)

            # Read peer's handshake
            data = await reader.readline()
            if not data:
                writer.close()
                return False
            peer_info = json.loads(data.decode().strip())
            peer_id = peer_info.get("node_id", f"peer_{peer_port}")

            self._peers[peer_id] = writer
            print(f"[{self.node_id}] Connected to peer '{peer_id}' at {peer_host}:{peer_port}")

            # Start listening for messages from this peer
            asyncio.create_task(self._peer_reader(peer_id, reader, writer))
            return True
        except Exception as e:
            print(f"[{self.node_id}] Failed to connect to {peer_host}:{peer_port}: {e}")
            return False

    async def _handle_incoming(self, reader: asyncio.StreamReader, writer: asyncio.StreamWriter):
        """Bejövő kapcsolat kezelése (peer vagy kliens)."""
        peer_addr = writer.get_extra_info("peername")
        try:
            # Read handshake
            data = await reader.readline()
            if not data:
                writer.close()
                return
            msg = json.loads(data.decode().strip())

            if msg.get("type") == "handshake":
                peer_id = msg.get("node_id", f"peer_{peer_addr}")
                self._peers[peer_id] = writer
                # Respond with our handshake
                response = {
                    "type": "handshake",
                    "node_id": self.node_id,
                    "host": self.host,
                    "port": self.port,
                }
                await self._send_raw(writer, response)
                print(f"[{self.node_id}] Peer '{peer_id}' connected from {peer_addr}")
                asyncio.create_task(self._peer_reader(peer_id, reader, writer))
            else:
                writer.close()
        except Exception as e:
            print(f"[{self.node_id}] Incoming connection error: {e}")
            try:
                writer.close()
            except Exception:
                pass

    async def _peer_reader(self, peer_id: str, reader: asyncio.StreamReader, writer: asyncio.StreamWriter):
        """Folyamatosan olvassa a peertől érkező üzeneteket."""
        try:
            while self._running:
                data = await reader.readline()
                if not data:
                    break
                msg = json.loads(data.decode().strip())
                await self._handle_peer_message(peer_id, msg)
        except asyncio.IncompleteReadError:
            pass
        except Exception as e:
            print(f"[{self.node_id}] Peer reader error for '{peer_id}': {e}")
        finally:
            self._peers.pop(peer_id, None)
            try:
                writer.close()
            except Exception:
                pass
            print(f"[{self.node_id}] Peer '{peer_id}' disconnected.")

    async def _handle_peer_message(self, peer_id: str, msg: dict):
        """Feldolgoz egy peer-től érkező üzenetet."""
        msg_type = msg.get("type")
        if msg_type == "mesh_message":
            mesh_msg = MeshMessage.from_dict(msg["message"])
            await self._process_message(mesh_msg, from_peer=peer_id)
        elif msg_type == "subscribe_announce":
            # Peer announces its subscriptions so we can route efficiently
            pattern = msg.get("topic_pattern")
            subscriber_id = msg.get("subscriber_id")
            if pattern:
                sub = Subscription(
                    subscriber_id=f"{peer_id}::{subscriber_id}",
                    topic_pattern=pattern,
                    callback=None,  # remote — forward to peer
                )
                self.router.subscribe(sub)
                print(f"[{self.node_id}] Remote subscription from '{peer_id}': {pattern}")

    async def _send_raw(self, writer: asyncio.StreamWriter, data: dict):
        """Nyers JSON üzenet küldése."""
        raw = (json.dumps(data) + "\n").encode()
        writer.write(raw)
        await writer.drain()

    async def _send_to_peer(self, peer_id: str, data: dict):
        writer = self._peers.get(peer_id)
        if writer and not writer.is_closing():
            await self._send_raw(writer, data)

    async def _send_to_all_peers(self, data: dict, exclude: Optional[str] = None):
        tasks = []
        for pid, writer in list(self._peers.items()):
            if pid == exclude:
                continue
            if not writer.is_closing():
                tasks.append(self._send_raw(writer, data))
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)

    async def publish(self, topic: str, payload: Any, priority: MessagePriority = MessagePriority.NORMAL,
                      headers: Optional[Dict[str, str]] = None) -> str:
        """
        Üzenet publikálása egy témába.
        Visszatér az üzenet azonosítójával.
        """
        msg = MeshMessage(
            id=str(uuid.uuid4()),
            topic=topic,
            payload=payload,
            sender_id=self.node_id,
            timestamp=time.time(),
            priority=priority,
            headers=headers or {},
            ttl=10,
        )
        await self._process_message(msg, from_peer=None)
        return msg.id

    async def subscribe(self, topic_pattern: str,
                        callback: Optional[Callable[[MeshMessage], Awaitable[None]]] = None) -> str:
        """
        Feliratkozás egy témára (wildcard támogatással).
        Visszatér a feliratkozó azonosítójával.
        """
        subscriber_id = f"{self.node_id}::{uuid.uuid4().hex[:8]}"
        sub = Subscription(
            subscriber_id=subscriber_id,
            topic_pattern=topic_pattern,
            callback=callback,
        )
        async with self._lock:
            self.router.subscribe(sub)

        # Announce subscription to peers so they can route to us
        announce = {
            "type": "subscribe_announce",
            "subscriber_id": subscriber_id,
            "topic_pattern": topic_pattern,
        }
        await self._send_to_all_peers(announce)

        print(f"[{self.node_id}] Subscribed to '{topic_pattern}' (sub_id={subscriber_id})")
        return subscriber_id

    async def unsubscribe(self, subscriber_id: str):
        """Leiratkozás."""
        async with self._lock:
            self.router.unsubscribe(subscriber_id)
        print(f"[{self.node_id}] Unsubscribed: {subscriber_id}")

    async def _process_message(self, msg: MeshMessage, from_peer: Optional[str] = None):
        """
        Feldolgoz egy beérkező üzenetet:
        1. Deduplikáció (idempotencia)
        2. Lokális feliratkozók kézbesítése
        3. Továbbítás peer-eknek (ha van TTL)
        """
        # Dedup
        if msg.id in self._seen_messages:
            return
        self._seen_messages.add(msg.id)
        if len(self._seen_messages) > self._max_seen:
            # Trim old entries (simple approach)
            self._seen_messages = set(list(self._seen_messages)[-self._max_seen:])

        self.router.record_publish()

        # Find matching local subscriptions
        async with self._lock:
            matches = self.router.get_matching_subscriptions(msg.topic)

        if matches:
            self.router.record_routed(len(matches))
            for sub in matches:
                sub.message_count += 1
                if sub.callback:
                    try:
                        await sub.callback(msg)
                    except Exception as e:
                        print(f"[{self.node_id}] Callback error for sub {sub.subscriber_id}: {e}")
                # If subscription is from a remote peer (callback is None but subscriber_id has peer prefix)
                if sub.callback is None and "::" in sub.subscriber_id:
                    peer_id = sub.subscriber_id.split("::")[0]
                    await self._send_to_peer(peer_id, {
                        "type": "mesh_message",
                        "message": msg.to_dict(),
                    })
        else:
            self.router.record_dropped()

        # Forward to all peers (except sender) if TTL allows
        if msg.ttl > 0 and self._peers:
            msg.ttl -= 1
            await self._send_to_all_peers(
                {"type": "mesh_message", "message": msg.to_dict()},
                exclude=from_peer,
            )

    def get_stats(self) -> dict:
        return self.router.get_stats()

    def list_subscriptions(self) -> List[dict]:
        result = []
        for pattern, subs in self.router._subscriptions.items():
            for s in subs:
                result.append({
                    "subscriber_id": s.subscriber_id,
                    "topic_pattern": pattern,
                    "message_count": s.message_count,
                    "created_at": s.created_at,
                })
        return result


