async def demo_single_node():
    """Egyetlen node-on belüli pub/sub demo."""
    print("=" * 60)
    print("DEMO 1: Single-node topic-based pub/sub")
    print("=" * 60)

    node = MeshNode("node_alpha")
    await node.start()

    received: List[MeshMessage] = []

    async def handler(msg: MeshMessage):
        received.append(msg)
        print(f"  [handler] topic='{msg.topic}' payload={msg.payload}")

    # Subscribe to different topics
    await node.subscribe("sensors.temperature", handler)
    await node.subscribe("sensors.*", handler)  # wildcard
    await node.subscribe("alerts.#", handler)   # multi-level wildcard
    await node.subscribe("system.status", handler)

    # Publish messages
    print("\n--- Publishing messages ---")
    await node.publish("sensors.temperature", {"value": 23.5, "unit": "C"})
    await node.publish("sensors.humidity", {"value": 45, "unit": "%"})
    await node.publish("sensors.pressure", {"value": 1013, "unit": "hPa"})
    await node.publish("alerts.critical.overheat", "Server room overheating!")
    await node.publish("alerts.warning.disk", "Disk usage 85%")
    await node.publish("system.status", "All systems nominal")
    await node.publish("news.tech", "This should not match any subscription")

    await asyncio.sleep(0.3)

    print(f"\n--- Results ---")
    print(f"Total messages received by handlers: {len(received)}")
    stats = node.get_stats()
    print(f"Stats: {json.dumps(stats, indent=2)}")

    print(f"\nSubscriptions:")
    for s in node.list_subscriptions():
        print(f"  {s['subscriber_id'][:30]}  topic={s['topic_pattern']}  msgs={s['message_count']}")

    await node.stop()
    return received


async def demo_multi_node():
    """Több node közötti pub/sub demo — csak releváns üzenetek útválasztása."""
    print("\n" + "=" * 60)
    print("DEMO 2: Multi-node mesh with topic routing")
    print("=" * 60)

    # Create 3 nodes
    node_a = MeshNode("node_A", port=0)
    node_b = MeshNode("node_B", port=0)
    node_c = MeshNode("node_C", port=0)

    await node_a.start()
    await node_b.start()
    await node_c.start()

    # Connect: A <-> B <-> C (chain topology)
    await node_a.connect_to_peer("127.0.0.1", node_b.port)
    await asyncio.sleep(0.1)
    await node_b.connect_to_peer("127.0.0.1", node_c.port)
    await asyncio.sleep(0.2)

    received_a: List[str] = []
    received_b: List[str] = []
    received_c: List[str] = []

    async def make_handler(name, store):
        async def h(msg: MeshMessage):
            store.append(msg.topic)
            print(f"  [{name}] Received: topic='{msg.topic}' payload={msg.payload}")
        return h

    h_a = await make_handler("NodeA", received_a)
    h_b = await make_handler("NodeB", received_b)
    h_c = await make_handler("NodeC", received_c)

    # Node A subscribes to "sensors.temperature"
    await node_a.subscribe("sensors.temperature", h_a)

    # Node B subscribes to "sensors.*" (wildcard — matches all sensor topics)
    await node_b.subscribe("sensors.*", h_b)

    # Node C subscribes to "alerts.#" (multi-level wildcard)
    await node_c.subscribe("alerts.#", h_c)

    await asyncio.sleep(0.3)  # let subscription announcements propagate

    print("\n--- Publishing from Node A ---")
    await node_a.publish("sensors.temperature", {"temp": 22.0})
    await asyncio.sleep(0.2)
    # Expected: A receives (local sub), B receives (wildcard), C does NOT

    print("\n--- Publishing from Node C ---")
    await node_c.publish("alerts.critical.cpu", "CPU on fire!")
    await asyncio.sleep(0.2)
    # Expected: C receives (local sub), A and B do NOT

    print("\n--- Publishing from Node B ---")
    await node_b.publish("sensors.humidity", {"humidity": 55})
    await asyncio.sleep(0.2)
    # Expected: B receives (wildcard), A does NOT (only temp), C does NOT

    print("\n--- Publishing unrelated topic ---")
    await node_a.publish("random.topic", "nobody cares")
    await asyncio.sleep(0.2)
    # Expected: nobody receives

    print(f"\n--- Results ---")
    print(f"Node A received topics: {received_a}")
    print(f"Node B received topics: {received_b}")
    print(f"Node C received topics: {received_c}")

    print(f"\nNode A stats: {json.dumps(node_a.get_stats(), indent=2)}")
    print(f"Node B stats: {json.dumps(node_b.get_stats(), indent=2)}")
    print(f"Node C stats: {json.dumps(node_c.get_stats(), indent=2)}")

    # Verify correctness
    assert "sensors.temperature" in received_a, "Node A should receive temp"
    assert "sensors.temperature" in received_b, "Node B should receive temp (wildcard)"
    assert "sensors.humidity" in received_b, "Node B should receive humidity (wildcard)"
    assert "alerts.critical.cpu" in received_c, "Node C should receive alert"
    assert "random.topic" not in received_a, "Node A should NOT receive random"
    assert "random.topic" not in received_b, "Node B should NOT receive random"
    assert "random.topic" not in received_c, "Node C should NOT receive random"
    assert "sensors.humidity" not in received_a, "Node A should NOT receive humidity"
    assert "alerts.critical.cpu" not in received_a, "Node A should NOT receive alerts"
    assert "alerts.critical.cpu" not in received_b, "Node B should NOT receive alerts"

    print("\n✓ All assertions passed — only relevant messages were routed!")

    await node_a.stop()
    await node_b.stop()
    await node_c.stop()


async def demo_unsubscribe():
    """Leiratkozás demo."""
    print("\n" + "=" * 60)
    print("DEMO 3: Unsubscribe behavior")
    print("=" * 60)

    node = MeshNode("node_unsub")
    await node.start()

    received = []

    async def handler(msg: MeshMessage):
        received.append(msg.topic)
        print(f"  [handler] {msg.topic}: {msg.payload}")

    sub_id = await node.subscribe("test.topic", handler)
    await node.publish("test.topic", "message 1")
    await asyncio.sleep(0.1)
    print(f"  Received so far: {received}")

    await node.unsubscribe(sub_id)
    await node.publish("test.topic", "message 2 (should not arrive)")
    await asyncio.sleep(0.1)
    print(f"  Received after unsubscribe: {received}")

    assert received == ["test.topic"], "Should only receive message 1"
    print("  ✓ Unsubscribe works correctly!")

    await node.stop()


def test_topic_matching():
    """Unit tesztek a topic_matches függvényre."""
    print("\n" + "=" * 60)
    print("UNIT TESTS: topic_matches()")
    print("=" * 60)

    tests = [
        ("sensors.temp", "sensors.temp", True),
        ("sensors.*", "sensors.temp", True),
        ("sensors.*", "sensors.humidity", True),
        ("sensors.*", "sensors.temp.room1", False),  # * matches one level only
        ("sensors.#", "sensors.temp.room1", True),   # # matches multiple levels
        ("sensors.#", "sensors", False),              # # needs at least one level
        ("*", "anything", True),
        ("*", "anything.nested", False),
        ("#", "a.b.c.d", True),
        ("alerts.critical.*", "alerts.critical.fire", True),
        ("alerts.critical.*", "alerts.warning.fire", False),
        ("exact", "exact", True),
        ("exact", "different", False),
        ("a.b.c", "a.b.c", True),
        ("a.b.c", "a.b.d", False),
    ]

    passed = 0
    for pattern, topic, expected in tests:
        result = topic_matches(pattern, topic)
        status = "✓" if result == expected else "✗"
        if result == expected:
            passed += 1
        print(f"  {status} topic_matches('{pattern}', '{topic}') = {result} (expected {expected})")

    print(f"\n  {passed}/{len(tests)} tests passed")
    assert passed == len(tests), "Some topic matching tests failed!"
    print("  ✓ All topic matching tests passed!")


